const doc = 'PRUEBA83-' + Date.now();
return [
  { json: { caso: '1 clasificar documento (L0)', esperado: 'permitir', modo: 'evaluar', accion: 'clasificar_documento' } },
  { json: { caso: '2 pago de $ 1.200.000', esperado: 'pedir aprobación, sin doble control', modo: 'evaluar', accion: 'aprobar_pago', monto: 1200000 } },
  { json: { caso: '3 pago de $ 6.000.000', esperado: 'pedir aprobación con doble control', modo: 'evaluar', accion: 'aprobar_pago', monto: 6000000 } },
  { json: { caso: '4 cambiar CBU (L4)', esperado: 'bloquear', modo: 'evaluar', accion: 'cambiar_cbu' } },
  { json: { caso: '5 acción desconocida', esperado: 'bloquear (falla segura)', modo: 'evaluar', accion: 'borrar_todo' } },
  { json: { caso: '6 pedir aprobación de $ 6.000.000', esperado: 'aprobación creada, doble control, con link', modo: 'pedir',
            automatizacion_id: 'A07', objeto: doc, accion: 'aprobar_pago', monto: 6000000, motivo: 'Prueba del motor de políticas' } },
];

const casos = $('CA83P_Casos').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ok = [
  r => r.permitido === true && r.decision === 'permitir',
  r => r.requiere_aprobacion === true && r.doble_control === false,
  r => r.requiere_aprobacion === true && r.doble_control === true && r.segundo_aprobador === 'Socio gerente',
  r => r.bloqueado === true,
  r => r.bloqueado === true && /Falla segura/.test(r.motivo || ''),
  r => !!r.aprobacion_id && r.nivel === 'L3 + doble control' && /aprobacion_id=/.test(r.link_formulario || ''),
];
return casos.map((c, i) => { const r = res[i] || {};
  return { json: { caso: c.caso, esperado: c.esperado, resultado: ok[i](r) ? 'PASA' : 'FALLA', detalle: JSON.stringify(r).slice(0, 300), aprobacion_id: r.aprobacion_id ?? null } }; });

const filas = $('CA83P_Evaluar_1_a_6').all().map(i => i.json);
const r = $input.first().json;
filas.push({ caso: '7 consultar la aprobación del caso 6', esperado: 'pendiente; el silencio no es un sí',
  resultado: r.estado === 'pendiente' && r.aprobado === false ? 'PASA' : 'FALLA', detalle: JSON.stringify(r).slice(0, 300), aprobacion_id: r.aprobacion_id });
return filas.map(f => ({ json: f }));
